export type TechName =
  | "C++"
  | "C"
  | "Python"
  | "TypeScript"
  | "Go"
  | "Java"
  | "React"
  | "Tailwind"
  | "Tailwind CSS"
  | "Node.js"
  | "Docker"
  | "AWS"
  | "GCP"
  | "PostgreSQL"
  | "MySQL"
  | "MongoDB"
  | "Redis"
  | "Kafka"
  | "Git"
  | "Linux"
  | "GraphQL"
  | "GitHub"
  | "Next.js"
  | "Kubernetes"
  | "OpenCV"
  | "NumPy"
  | "Firebase"
  | "Jenkins"
  | "MediaPipe"
  | "REST"
  | "OpenTelemetry";

export const TECH_ICONS: Record<TechName, (p: IconProps) => ReactElement> = {
  "C++": CppIcon,
  C: CppIcon,
  Python: PythonIcon,
  TypeScript: TypeScriptIcon,
  Go: GoIcon,
  Java: JavaIcon,
  React: ReactIcon,
  Tailwind: TailwindIcon,
  "Tailwind CSS": TailwindIcon,
  "Node.js": NodeIcon,
  Docker: DockerIcon,
  AWS: AwsIcon,
  GCP: GcpIcon,
  PostgreSQL: PostgresIcon,
  MySQL: MysqlIcon,
  MongoDB: MongoIcon,
  Redis: RedisIcon,
  Kafka: KafkaIcon,
  Git: GitIcon,
  Linux: LinuxIcon,
  GraphQL: GraphQLIcon,
  GitHub: GitHubIcon,
  "Next.js": NextIcon,
  Kubernetes: KubernetesIcon,
  OpenCV: OpenCVIcon,
  NumPy: NumpyIcon,
  Firebase: FirebaseIcon,
  Jenkins: JenkinsIcon,
  MediaPipe: MediaPipeIcon,
  REST: RestIcon,
  OpenTelemetry: OpenTelemetryIcon,
};

export function TechIcon({ name, ...props }: IconProps & { name: TechName }) {
  const Cmp = TECH_ICONS[name];
  if (!Cmp) return null;
  return <Cmp {...props} />;
}
